if(msg.payload===''||typeof msg.payload==='boolean'||!Number.isFinite(Number(msg.payload))||Number(msg.payload)<0||Number(msg.payload)>100)return null;
const binding=explicitCarSoc(car);if(!binding.anchor)return null;
flow.set(key,{soc:Number(msg.payload),at:Date.now(),anchor:binding.anchor});
flow.set('ess_'+car+'_soc_estimator',null);return {payload:Date.now()};

function costEreOpening(snapshot,ledger,now){
    const at=typeof snapshot?.at==='number'?snapshot.at:Date.parse(snapshot?.at);
    if(!Number.isFinite(at)||at>now||typeof snapshot?.kwh!=='number'||!Number.isFinite(snapshot.kwh)||snapshot.kwh<0||typeof snapshot?.euros!=='number'||!Number.isFinite(snapshot.euros)||snapshot.euros<0)return null;
    const total=(ledger?.cars?.audi?.kwh||0)+(ledger?.cars?.jeep?.kwh||0);
    const after=!ledger||ledger.startedAt>=at?total:(ledger.quarters||[]).filter(q=>q.start>=at).reduce((sum,q)=>sum+q.audiKwh+q.jeepKwh,0);
    return {at,kwh:snapshot.kwh,euros:snapshot.euros,trackedKwh:Math.max(0,total-after)};
}
if(msg.topic!=='ess/costs/ere-opening'&&!msg.ereOpeningFile)return null;
if(msg.ereOpeningFile&&flow.get('ess_ere_opening_balance'))return null;
let data=msg.payload;try{if(typeof data==='string')data=JSON.parse(data);}catch{return null;}
const balance=costEreOpening(data,flow.get('ess_energy_cost_ledger'),Date.now());if(!balance)return null;
flow.set('ess_ere_opening_balance',balance);return {payload:Date.now()};

function providerYearBalance(snapshot,ledger,now) {
    if(!snapshot||!ledger||snapshot.year!==Number(new Intl.DateTimeFormat('en',{timeZone:'Europe/Amsterdam',year:'numeric'}).format(new Date(now))))return null;
    const fields=['importKwh','importEuros','exportKwh','exportEuros','netEuros'];
    if(!fields.every(k=>typeof snapshot[k]==='number'&&Number.isFinite(snapshot[k]))||snapshot.importKwh<0||snapshot.exportKwh<0)return null;
    const anchor=snapshot.anchor;
    if(!anchor||!['gridKwh','gridCost','exportKwh','exportRevenue'].every(k=>Number.isFinite(anchor[k]))||snapshot.ledgerStartedAt!==ledger.startedAt)return null;
    const t=ledger.total;
    return {year:snapshot.year,at:snapshot.at,importKwh:snapshot.importKwh+t.gridKwh-anchor.gridKwh,
        importEuros:snapshot.importEuros+t.gridCost-anchor.gridCost,exportKwh:snapshot.exportKwh+t.exportKwh-anchor.exportKwh,
        exportEuros:snapshot.exportEuros+t.exportRevenue-anchor.exportRevenue,
        netEuros:snapshot.netEuros+t.gridCost-anchor.gridCost-(t.exportRevenue-anchor.exportRevenue)};
}
let s;try{s=JSON.parse(msg.payload);}catch{return null;}
if(flow.get('ess_provider_year_balance')||!providerYearBalance(s,flow.get('ess_energy_cost_ledger'),Date.now()))return null;
flow.set('ess_provider_year_balance',s);return {payload:Date.now()};

function heatPumpSettings(v={}) {
    const number=(key,fallback,min,max)=>typeof v[key]==='number'&&Number.isFinite(v[key])&&v[key]>=min&&v[key]<=max?v[key]:fallback;
    const offW=number('offW',150,0,2000),onW=Math.max(offW+50,number('onW',300,50,5000));
    return {offW,onW,highW:Math.max(onW+100,number('highW',3000,500,15000))};
}
if(msg.topic!=='ess/heat-pump/settings'||!msg.payload||typeof msg.payload!=='object')return null;flow.set('ess_heat_pump_settings',heatPumpSettings(msg.payload));return {payload:Date.now()};
